    "query_audit": {
        "count": 254,
        "sql": [
            "\r\n    SELECT \r\n        u.nome_usuario, \r\n        iu.cnpj, \r\n        e.rua, e.bairro, e.numero, e.complemento, e.cep, \r\n        iu.nome_empresarial, iu.estado_civil, iu.cpf, \r\n        ec.rua_cnpj, ec.numero_cnpj, ec.bairro_cnpj, ec.localidade_cnpj, ec.uf_cnpj, ec.cep_cnpj \r\n    FROM \r\n        usuario u \r\n    LEFT JOIN \r\n        informacoes_usuario iu ON iu.usuario_id = u.idusuario \r\n    LEFT JOIN \r\n        endereco e ON e.usuario_id = u.idusuario \r\n    LEFT JOIN \r\n        endereco_cnpj ec ON ec.usuario_id = u.idusuario \r\n    WHERE \r\n        u.idcolaborador = ?",
            "SELECT \r\n        fi.colaborador_id,\r\n        'funcao_imagem' AS origem,\r\n        fi.idfuncao_imagem AS identificador,\r\n        fi.imagem_id,\r\n        ico.imagem_nome,\r\n        fi.funcao_id,\r\n        CASE \r\n            WHEN fi.funcao_id = 4 THEN \r\n                    CASE \r\n                        WHEN EXISTS (\r\n                            SELECT 1 \r\n                            FROM funcao_imagem fi_sub\r\n                            JOIN funcao f_sub ON fi_sub.funcao_id = f_sub.idfuncao\r\n                            WHERE fi_sub.imagem_id = fi.imagem_id \r\n                            AND f_sub.nome_funcao = 'Pré-Finalização'\r\n                        ) OR hi_snap.status_id = 1\r\n                        THEN 'Finalização Parcial'\r\n                        ELSE 'Finalização Completa'\r\n                    END \r\n            ELSE f.nome_funcao \r\n        END AS nome_funcao,\r\n        fi.status,\r\n        fi.prazo,\r\n        fi.pagamento,\r\n        fi.valor,\r\n        fi.data_pagamento,\r\n        CASE WHEN fi.funcao_id = 4 THEN (\r\n            SELECT COUNT(1)\r\n            FROM pagamento_itens pi\r\n            JOIN funcao_imagem fi_pi ON pi.origem = 'funcao_imagem' AND pi.origem_id = fi_pi.idfuncao_imagem\r\n            WHERE fi_pi.imagem_id = fi.imagem_id AND fi_pi.funcao_id = 4 AND pi.observacao = 'Finalização Parcial'\r\n        ) ELSE 0 END AS pago_parcial_count,\r\n        CASE WHEN fi.funcao_id = 4 THEN (\r\n            SELECT COUNT(1)\r\n            FROM pagamento_itens pi\r\n            JOIN funcao_imagem fi_pi ON pi.origem = 'funcao_imagem' AND pi.origem_id = fi_pi.idfuncao_imagem\r\n            WHERE fi_pi.imagem_id = fi.imagem_id AND fi_pi.funcao_id = 4 AND pi.observacao = 'Pago Completa'\r\n        ) ELSE 0 END AS pago_completa_count\r\n    FROM \r\n        funcao_imagem fi\r\n    JOIN \r\n        imagens_cliente_obra ico ON fi.imagem_id = ico.idimagens_cliente_obra\r\n    JOIN \r\n        obra o ON ico.obra_id = o.idobra\r\n    JOIN \r\n        funcao f ON fi.funcao_id = f.idfuncao\r\n    LEFT JOIN (\r\n        SELECT h1.imagem_id, MAX(h1.status_id) AS status_id\r\n        FROM historico_imagens h1\r\n        INNER JOIN (\r\n            SELECT imagem_id, MAX(data_movimento) AS max_data\r\n            FROM historico_imagens\r\n            WHERE data_movimento <= ?\r\n            GROUP BY imagem_id\r\n        ) hm ON hm.imagem_id = h1.imagem_id AND hm.max_data = h1.data_movimento\r\n        GROUP BY h1.imagem_id\r\n    ) hi_snap ON hi_snap.imagem_id = ico.idimagens_cliente_obra\r\n    WHERE \r\n        fi.colaborador_id = ? AND (\r\n            (\r\n                (fi.status = 'Finalizado' OR fi.status = 'Em aprovação' OR fi.status = 'Ajuste' OR fi.status = 'Aprovado com ajustes' OR fi.status = 'Aprovado')\r\n                AND (YEAR(fi.prazo) = ? AND MONTH(fi.prazo) = ?)\r\n            )\r\n            OR EXISTS (\r\n                SELECT 1 FROM log_alteracoes la\r\n                WHERE la.funcao_imagem_id = fi.idfuncao_imagem\r\n                  AND MONTH(la.data) = ? AND YEAR(la.data) = ?\r\n                  AND LOWER(TRIM(la.status_novo)) IN ('finalizado', 'em aprovação', 'ajuste', 'aprovado com ajustes', 'aprovado')\r\n            )\r\n        ) ORDER BY ico.obra_id, ico.idimagens_cliente_obra, fi.funcao_id",
            "SELECT colaborador_id, funcao_id, valor FROM funcao_colaborador WHERE colaborador_id IN (?)",
            "SELECT idfuncao_imagem FROM funcao_imagem WHERE idfuncao_imagem IN (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) AND valor_aprovado = 1",
            "SELECT fi.*, 'funcao_imagem' origem, fi.idfuncao_imagem origem_id, i.tipo_imagem, i.imagem_nome,\r\n        CASE WHEN fi.funcao_id=4 AND (EXISTS(SELECT 1 FROM funcao_imagem fp JOIN funcao f ON f.idfuncao=fp.funcao_id WHERE fp.imagem_id=fi.imagem_id AND f.nome_funcao='Pré-Finalização') OR\r\n        (SELECT h.status_id FROM historico_imagens h WHERE h.imagem_id=fi.imagem_id AND h.data_movimento < ? ORDER BY h.data_movimento DESC,h.status_id DESC LIMIT 1)=1) THEN 1 ELSE 0 END parcial\r\n        FROM funcao_imagem fi JOIN imagens_cliente_obra i ON i.idimagens_cliente_obra=fi.imagem_id\r\n        WHERE (fi.colaborador_id=? OR (?=8 AND fi.colaborador_id IN (23,40) AND fi.funcao_id=4))\r\n        AND ((LOWER(TRIM(fi.status)) IN ('finalizado','em aprovação','ajuste','aprovado com ajustes','aprovado') AND fi.prazo>=? AND fi.prazo<?)\r\n          OR EXISTS(SELECT 1 FROM log_alteracoes l WHERE l.funcao_imagem_id=fi.idfuncao_imagem AND l.data>=? AND l.data<? AND LOWER(TRIM(l.status_novo)) IN ('finalizado','em aprovação','ajuste','aprovado com ajustes','aprovado')))",
            "SELECT a.*, 'acompanhamento' origem, a.idacompanhamento origem_id, 0 parcial FROM acompanhamento a WHERE a.colaborador_id=? AND a.data>=? AND a.data<?",
            "SELECT fa.*, 'funcao_animacao' origem, fa.id origem_id, 0 parcial FROM funcao_animacao fa JOIN animacao a ON a.idanimacao=fa.animacao_id WHERE fa.colaborador_id=? AND a.data_anima>=? AND a.data_anima<? AND LOWER(TRIM(fa.status)) IN ('finalizado','em aprovação','ajuste','aprovado com ajustes','aprovado')",
            "SELECT pi.* FROM pagamento_itens pi JOIN pagamentos p ON p.idpagamento=pi.pagamento_id WHERE p.colaborador_id=?",
            "SELECT pi.*,p.colaborador_id,p.mes_ref FROM pagamento_itens pi JOIN pagamentos p ON p.idpagamento=pi.pagamento_id WHERE p.colaborador_id=? ORDER BY pi.idpagamento_item",
            "SELECT idcolaborador,nome_colaborador,ativo,valor_fixo FROM colaborador WHERE idcolaborador=?",
            "SELECT id,competencia,status,payload_enviado,arquivo_nome FROM adendos WHERE colaborador_id=? AND competencia=?",
            "SELECT \r\n        fi.colaborador_id,\r\n        'funcao_imagem' AS origem,\r\n        fi.idfuncao_imagem AS identificador,\r\n        fi.imagem_id,\r\n        ico.imagem_nome,\r\n        fi.funcao_id,\r\n        CASE \r\n            WHEN fi.funcao_id = 4 THEN \r\n                    CASE \r\n                        WHEN EXISTS (\r\n                            SELECT 1 \r\n                            FROM funcao_imagem fi_sub\r\n                            JOIN funcao f_sub ON fi_sub.funcao_id = f_sub.idfuncao\r\n                            WHERE fi_sub.imagem_id = fi.imagem_id \r\n                            AND f_sub.nome_funcao = 'Pré-Finalização'\r\n                        ) OR hi_snap.status_id = 1\r\n                        THEN 'Finalização Parcial'\r\n                        ELSE 'Finalização Completa'\r\n                    END \r\n            ELSE f.nome_funcao \r\n        END AS nome_funcao,\r\n        fi.status,\r\n        fi.prazo,\r\n        fi.pagamento,\r\n        fi.valor,\r\n        fi.data_pagamento,\r\n        CASE WHEN fi.funcao_id = 4 THEN (\r\n            SELECT COUNT(1)\r\n            FROM pagamento_itens pi\r\n            JOIN funcao_imagem fi_pi ON pi.origem = 'funcao_imagem' AND pi.origem_id = fi_pi.idfuncao_imagem\r\n            WHERE fi_pi.imagem_id = fi.imagem_id AND fi_pi.funcao_id = 4 AND pi.observacao = 'Finalização Parcial'\r\n        ) ELSE 0 END AS pago_parcial_count,\r\n        CASE WHEN fi.funcao_id = 4 THEN (\r\n            SELECT COUNT(1)\r\n            FROM pagamento_itens pi\r\n            JOIN funcao_imagem fi_pi ON pi.origem = 'funcao_imagem' AND pi.origem_id = fi_pi.idfuncao_imagem\r\n            WHERE fi_pi.imagem_id = fi.imagem_id AND fi_pi.funcao_id = 4 AND pi.observacao = 'Pago Completa'\r\n        ) ELSE 0 END AS pago_completa_count\r\n    FROM \r\n        funcao_imagem fi\r\n    JOIN \r\n        imagens_cliente_obra ico ON fi.imagem_id = ico.idimagens_cliente_obra\r\n    JOIN \r\n        obra o ON ico.obra_id = o.idobra\r\n    JOIN \r\n        funcao f ON fi.funcao_id = f.idfuncao\r\n    LEFT JOIN (\r\n        SELECT h1.imagem_id, h1.status_id\r\n        FROM historico_imagens h1\r\n        INNER JOIN (\r\n            SELECT imagem_id, MAX(data_movimento) AS max_data\r\n            FROM historico_imagens\r\n            WHERE data_movimento <= ?\r\n            GROUP BY imagem_id\r\n        ) hm ON hm.imagem_id = h1.imagem_id AND hm.max_data = h1.data_movimento\r\n    ) hi_snap ON hi_snap.imagem_id = ico.idimagens_cliente_obra\r\n    WHERE \r\n        fi.colaborador_id = ?\r\n        AND (\r\n            (\r\n                (fi.status = 'Finalizado' OR fi.status = 'Em aprovação' OR fi.status = 'Ajuste' OR fi.status = 'Aprovado com ajustes' OR fi.status = 'Aprovado')\r\n                AND (YEAR(fi.prazo) = ? AND MONTH(fi.prazo) = ?)\r\n            )\r\n            OR EXISTS (\r\n                SELECT 1 FROM log_alteracoes la\r\n                WHERE la.funcao_imagem_id = fi.idfuncao_imagem\r\n                  AND MONTH(la.data) = ? AND YEAR(la.data) = ?\r\n                  AND LOWER(TRIM(la.status_novo)) IN ('finalizado', 'em aprovação', 'ajuste', 'aprovado com ajustes', 'aprovado')\r\n            )\r\n        )\r\n    ORDER BY ico.obra_id, ico.idimagens_cliente_obra, fi.funcao_id",
            "SELECT \r\n    fi.colaborador_id,\r\n    'funcao_imagem' AS origem,\r\n    fi.idfuncao_imagem AS identificador,\r\n    fi.imagem_id,\r\n    ico.imagem_nome,\r\n    fi.funcao_id,\r\n    CASE \r\n        WHEN fi.funcao_id = 4 THEN \r\n                CASE \r\n                    WHEN EXISTS (\r\n                        SELECT 1 \r\n                        FROM funcao_imagem fi_sub\r\n                        JOIN funcao f_sub ON fi_sub.funcao_id = f_sub.idfuncao\r\n                        WHERE fi_sub.imagem_id = fi.imagem_id \r\n                        AND f_sub.nome_funcao = 'Pré-Finalização'\r\n                    ) OR hi_snap.status_id = 1\r\n                    THEN 'Finalização Parcial'\r\n                    ELSE 'Finalização Completa'\r\n                END \r\n        ELSE f.nome_funcao \r\n    END AS nome_funcao,\r\n    fi.status,\r\n    fi.prazo,\r\n    fi.pagamento,\r\n    fi.valor,\r\n    fi.data_pagamento,\r\n    CASE WHEN fi.funcao_id = 4 THEN (\r\n        SELECT COUNT(1)\r\n        FROM pagamento_itens pi\r\n        JOIN funcao_imagem fi_pi ON pi.origem = 'funcao_imagem' AND pi.origem_id = fi_pi.idfuncao_imagem\r\n        WHERE fi_pi.imagem_id = fi.imagem_id AND fi_pi.funcao_id = 4 AND pi.observacao = 'Finalização Parcial'\r\n    ) ELSE 0 END AS pago_parcial_count,\r\n    CASE WHEN fi.funcao_id = 4 THEN (\r\n        SELECT COUNT(1)\r\n        FROM pagamento_itens pi\r\n        JOIN funcao_imagem fi_pi ON pi.origem = 'funcao_imagem' AND pi.origem_id = fi_pi.idfuncao_imagem\r\n        WHERE fi_pi.imagem_id = fi.imagem_id AND fi_pi.funcao_id = 4 AND pi.observacao = 'Pago Completa'\r\n    ) ELSE 0 END AS pago_completa_count,\r\n    o.idobra AS obra_id,\r\nNULL AS animacao_id_ordem,\r\n1 AS tem_par_animacao_pos\r\nFROM \r\n    funcao_imagem fi\r\nJOIN \r\n    imagens_cliente_obra ico ON fi.imagem_id = ico.idimagens_cliente_obra\r\nJOIN \r\n    obra o ON ico.obra_id = o.idobra\r\nJOIN \r\n    funcao f ON fi.funcao_id = f.idfuncao\r\nLEFT JOIN (\r\n        SELECT h1.imagem_id, MAX(h1.status_id) AS status_id\r\n        FROM historico_imagens h1\r\n        INNER JOIN (\r\n            SELECT imagem_id, MAX(data_movimento) AS max_data\r\n            FROM historico_imagens\r\n            WHERE data_movimento <= ?\r\n            GROUP BY imagem_id\r\n        ) hm ON hm.imagem_id = h1.imagem_id AND hm.max_data = h1.data_movimento\r\n        GROUP BY h1.imagem_id\r\n    ) hi_snap ON hi_snap.imagem_id = ico.idimagens_cliente_obra\r\nWHERE \r\n    fi.colaborador_id = ? AND (\r\n            (\r\n                (fi.status = 'Finalizado' OR fi.status = 'Em aprovação' OR fi.status = 'Ajuste' OR fi.status = 'Aprovado com ajustes' OR fi.status = 'Aprovado')\r\n                AND (YEAR(fi.prazo) = ? AND MONTH(fi.prazo) = ?)\r\n            )\r\n            OR EXISTS (\r\n                SELECT 1 FROM log_alteracoes la\r\n                WHERE la.funcao_imagem_id = fi.idfuncao_imagem\r\n                  AND MONTH(la.data) = ? AND YEAR(la.data) = ?\r\n                  AND LOWER(TRIM(la.status_novo)) IN ('finalizado', 'em aprovação', 'ajuste', 'aprovado com ajustes', 'aprovado')\r\n            )\r\n        ) \r\nUNION ALL\r\nSELECT \r\n    fa.colaborador_id,\r\n    'funcao_animacao' AS origem,\r\n    fa.id AS identificador,\r\n    an.imagem_id,\r\n    CONCAT(\r\n  ico.imagem_nome, \r\n  ' - ', \r\n  CONCAT(\r\n    UPPER(LEFT(an.tipo_animacao, 1)), \r\n    LOWER(SUBSTRING(an.tipo_animacao, 2))\r\n  )\r\n) AS imagem_nome,\r\n    fa.funcao_id,\r\n    f.nome_funcao AS nome_funcao,\r\n    fa.status,\r\n    fa.prazo as prazo,\r\n    fa.pagamento,\r\n    fa.valor,\r\n    fa.data_pagamento,\r\n    NULL AS pago_parcial_count,\r\n    NULL AS pago_completa_count,\r\n    an.obra_id,\r\n    fa.animacao_id AS animacao_id_ordem,\r\n    CASE\r\n    WHEN EXISTS (\r\n        SELECT 1\r\n        FROM funcao_animacao fa_pair\r\n        WHERE fa_pair.animacao_id = fa.animacao_id\r\n          AND fa_pair.colaborador_id = fa.colaborador_id\r\n          AND fa_pair.funcao_id IN (5, 10)\r\n        GROUP BY fa_pair.animacao_id, fa_pair.colaborador_id\r\n        HAVING COUNT(DISTINCT fa_pair.funcao_id) = 2\r\n    )\r\n    THEN 0\r\n    ELSE 1\r\nEND AS tem_par_animacao_pos\r\nFROM \r\n    funcao_animacao fa\r\nJOIN\r\n    animacao an ON fa.animacao_id = an.idanimacao\r\nJOIN\r\n    funcao f ON fa.funcao_id = f.idfuncao\r\nLEFT JOIN \r\n    imagens_cliente_obra ico ON an.imagem_id = ico.idimagens_cliente_obra\r\nWHERE \r\n    fa.colaborador_id = ? AND fa.status IN ('Finalizado', 'Em aprovação', 'Ajuste', 'Aprovado com ajustes', 'Aprovado') AND YEAR(fa.prazo) = ? AND MONTH(fa.prazo) = ?\r\nORDER BY\r\n    obra_id,\r\n    tem_par_animacao_pos ASC,\r\n    animacao_id_ordem,\r\n    CASE\r\n        WHEN funcao_id = 10 THEN 1\r\n        WHEN funcao_id = 5 THEN 2\r\n        ELSE 3\r\n    END,\r\n    funcao_id DESC,\r\n    imagem_nome",
            "SELECT idfuncao_imagem FROM funcao_imagem WHERE idfuncao_imagem IN (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) AND valor_aprovado = 1",
            "SELECT \r\n    fi.colaborador_id,\r\n    'funcao_imagem' AS origem,\r\n    fi.idfuncao_imagem AS identificador,\r\n    fi.imagem_id,\r\n    ico.imagem_nome,\r\n    fi.funcao_id,\r\n    CASE \r\n        WHEN fi.funcao_id = 4 THEN \r\n                CASE \r\n                    WHEN EXISTS (\r\n                        SELECT 1 \r\n                        FROM funcao_imagem fi_sub\r\n                        JOIN funcao f_sub ON fi_sub.funcao_id = f_sub.idfuncao\r\n                        WHERE fi_sub.imagem_id = fi.imagem_id \r\n                        AND f_sub.nome_funcao = 'Pré-Finalização'\r\n                    ) OR hi_snap.status_id = 1\r\n                    THEN 'Finalização Parcial'\r\n                    ELSE 'Finalização Completa'\r\n                END \r\n        ELSE f.nome_funcao \r\n    END AS nome_funcao,\r\n    fi.status,\r\n    fi.prazo,\r\n    fi.pagamento,\r\n    fi.valor,\r\n    fi.data_pagamento,\r\n    CASE WHEN fi.funcao_id = 4 THEN (\r\n        SELECT COUNT(1)\r\n        FROM pagamento_itens pi\r\n        JOIN funcao_imagem fi_pi ON pi.origem = 'funcao_imagem' AND pi.origem_id = fi_pi.idfuncao_imagem\r\n        WHERE fi_pi.imagem_id = fi.imagem_id AND fi_pi.funcao_id = 4 AND pi.observacao = 'Finalização Parcial'\r\n    ) ELSE 0 END AS pago_parcial_count,\r\n    CASE WHEN fi.funcao_id = 4 THEN (\r\n        SELECT COUNT(1)\r\n        FROM pagamento_itens pi\r\n        JOIN funcao_imagem fi_pi ON pi.origem = 'funcao_imagem' AND pi.origem_id = fi_pi.idfuncao_imagem\r\n        WHERE fi_pi.imagem_id = fi.imagem_id AND fi_pi.funcao_id = 4 AND pi.observacao = 'Pago Completa'\r\n    ) ELSE 0 END AS pago_completa_count,\r\n    o.idobra AS obra_id   \r\nFROM \r\n    funcao_imagem fi\r\nJOIN \r\n    imagens_cliente_obra ico ON fi.imagem_id = ico.idimagens_cliente_obra\r\nJOIN \r\n    obra o ON ico.obra_id = o.idobra\r\nJOIN \r\n    funcao f ON fi.funcao_id = f.idfuncao\r\nLEFT JOIN (\r\n    SELECT h1.imagem_id, h1.status_id\r\n    FROM historico_imagens h1\r\n    INNER JOIN (\r\n        SELECT imagem_id, MAX(data_movimento) AS max_data\r\n        FROM historico_imagens\r\n        WHERE data_movimento <= ?\r\n        GROUP BY imagem_id\r\n    ) hm ON hm.imagem_id = h1.imagem_id AND hm.max_data = h1.data_movimento\r\n) hi_snap ON hi_snap.imagem_id = ico.idimagens_cliente_obra\r\nWHERE \r\n    fi.colaborador_id = ?\r\n    AND (\r\n        (\r\n            (fi.status = 'Finalizado' OR fi.status = 'Em aprovação' OR fi.status = 'Ajuste' OR fi.status = 'Aprovado com ajustes' OR fi.status = 'Aprovado')\r\n            AND (YEAR(fi.prazo) = ? AND MONTH(fi.prazo) = ?)\r\n        )\r\n        OR EXISTS (\r\n            SELECT 1 FROM log_alteracoes la\r\n            WHERE la.funcao_imagem_id = fi.idfuncao_imagem\r\n              AND MONTH(la.data) = ? AND YEAR(la.data) = ?\r\n              AND LOWER(TRIM(la.status_novo)) IN ('finalizado', 'em aprovação', 'ajuste', 'aprovado com ajustes', 'aprovado')\r\n        )\r\n    )\r\nUNION ALL\r\nSELECT \r\n    fa.colaborador_id,\r\n    'funcao_animacao' AS origem,\r\n    fa.id AS identificador,\r\n    an.imagem_id,\r\n    ico.imagem_nome,\r\n    fa.funcao_id,\r\n    f.nome_funcao AS nome_funcao,\r\n    fa.status,\r\n    an.data_anima as prazo,\r\n    fa.pagamento,\r\n    fa.valor,\r\n    fa.data_pagamento,\r\n    NULL AS pago_parcial_count,\r\n    NULL AS pago_completa_count,\r\n    an.obra_id  \r\nFROM \r\n    funcao_animacao fa\r\nJOIN\r\n    animacao an ON fa.animacao_id = an.idanimacao\r\nJOIN\r\n    funcao f ON fa.funcao_id = f.idfuncao\r\nLEFT JOIN \r\n    imagens_cliente_obra ico ON an.imagem_id = ico.idimagens_cliente_obra\r\nWHERE \r\n    fa.colaborador_id = ? AND YEAR(an.data_anima) = ? AND MONTH(an.data_anima) = ?\r\nORDER BY obra_id, imagem_nome",
            "SELECT idfuncao_imagem FROM funcao_imagem WHERE idfuncao_imagem IN (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) AND valor_aprovado = 1",
            "SELECT \r\n    fi.colaborador_id,\r\n    'funcao_imagem' AS origem,\r\n    fi.idfuncao_imagem AS identificador,\r\n    fi.imagem_id,\r\n    ico.imagem_nome,\r\n    ico.tipo_imagem,\r\n    fi.funcao_id,\r\n    CASE \r\n        WHEN fi.funcao_id = 4 THEN \r\n                CASE \r\n                    WHEN EXISTS (\r\n                        SELECT 1 \r\n                        FROM funcao_imagem fi_sub\r\n                        JOIN funcao f_sub ON fi_sub.funcao_id = f_sub.idfuncao\r\n                        WHERE fi_sub.imagem_id = fi.imagem_id \r\n                        AND f_sub.nome_funcao = 'Pré-Finalização'\r\n                    ) OR hi_snap.status_id = 1\r\n                    THEN 'Finalização Parcial'\r\n                    ELSE 'Finalização Completa'\r\n                END \r\n        ELSE f.nome_funcao \r\n    END AS nome_funcao,\r\n    fi.status,\r\n    fi.prazo,\r\n    fi.pagamento,\r\n    fi.valor,\r\n    fi.data_pagamento,\r\n    CASE WHEN fi.funcao_id = 4 THEN (\r\n        SELECT COUNT(1)\r\n        FROM pagamento_itens pi\r\n        JOIN funcao_imagem fi_pi ON pi.origem = 'funcao_imagem' AND pi.origem_id = fi_pi.idfuncao_imagem\r\n        WHERE fi_pi.imagem_id = fi.imagem_id AND fi_pi.funcao_id = 4 AND pi.observacao = 'Finalização Parcial'\r\n    ) ELSE 0 END AS pago_parcial_count,\r\n    CASE WHEN fi.funcao_id = 4 THEN (\r\n        SELECT COUNT(1)\r\n        FROM pagamento_itens pi\r\n        JOIN funcao_imagem fi_pi ON pi.origem = 'funcao_imagem' AND pi.origem_id = fi_pi.idfuncao_imagem\r\n        WHERE fi_pi.imagem_id = fi.imagem_id AND fi_pi.funcao_id = 4 AND pi.observacao = 'Pago Completa'\r\n    ) ELSE 0 END AS pago_completa_count\r\nFROM \r\n    funcao_imagem fi\r\nJOIN \r\n    imagens_cliente_obra ico ON fi.imagem_id = ico.idimagens_cliente_obra\r\nJOIN \r\n    obra o ON ico.obra_id = o.idobra\r\nJOIN \r\n    funcao f ON fi.funcao_id = f.idfuncao\r\nLEFT JOIN (\r\n        SELECT h1.imagem_id, MAX(h1.status_id) AS status_id\r\n        FROM historico_imagens h1\r\n        INNER JOIN (\r\n            SELECT imagem_id, MAX(data_movimento) AS max_data\r\n            FROM historico_imagens\r\n            WHERE data_movimento <= ?\r\n            GROUP BY imagem_id\r\n        ) hm ON hm.imagem_id = h1.imagem_id AND hm.max_data = h1.data_movimento\r\n        GROUP BY h1.imagem_id\r\n    ) hi_snap ON hi_snap.imagem_id = ico.idimagens_cliente_obra\r\nWHERE \r\n    fi.colaborador_id = ? AND (\r\n            (\r\n                (fi.status = 'Finalizado' OR fi.status = 'Em aprovação' OR fi.status = 'Ajuste' OR fi.status = 'Aprovado com ajustes' OR fi.status = 'Aprovado')\r\n                AND (YEAR(fi.prazo) = ? AND MONTH(fi.prazo) = ?)\r\n            )\r\n            OR EXISTS (\r\n                SELECT 1 FROM log_alteracoes la\r\n                WHERE la.funcao_imagem_id = fi.idfuncao_imagem\r\n                  AND MONTH(la.data) = ? AND YEAR(la.data) = ?\r\n                  AND LOWER(TRIM(la.status_novo)) IN ('finalizado', 'em aprovação', 'ajuste', 'aprovado com ajustes', 'aprovado')\r\n            )\r\n        ) \r\nUNION ALL\r\nSELECT \r\n    fi.colaborador_id,\r\n    'funcao_imagem' AS origem,\r\n    fi.idfuncao_imagem AS identificador,\r\n    fi.imagem_id,\r\n    ico.imagem_nome,\r\n    ico.tipo_imagem,\r\n    fi.funcao_id,\r\n    CASE \r\n        WHEN fi.funcao_id = 4 THEN \r\n                CASE \r\n                    WHEN EXISTS (\r\n                        SELECT 1 \r\n                        FROM funcao_imagem fi_sub\r\n                        JOIN funcao f_sub ON fi_sub.funcao_id = f_sub.idfuncao\r\n                        WHERE fi_sub.imagem_id = fi.imagem_id \r\n                        AND f_sub.nome_funcao = 'Pré-Finalização'\r\n                    ) OR hi_snap.status_id = 1\r\n                    THEN CONCAT('Finalização Parcial - ', c.nome_colaborador)\r\n                    ELSE CONCAT('Finalização Completa - ', c.nome_colaborador)\r\n                END \r\n        ELSE f.nome_funcao \r\n    END AS nome_funcao,\r\n    fi.status,\r\n    fi.prazo,\r\n    CASE WHEN EXISTS (\r\n        SELECT 1 FROM pagamento_itens pi\r\n        WHERE pi.origem = 'funcao_imagem' AND pi.origem_id = fi.idfuncao_imagem\r\n          AND pi.observacao = 'Comissão Gestor'\r\n    ) THEN 1 ELSE 0 END AS pagamento,\r\n    fi.valor,\r\n    NULL AS data_pagamento,\r\n    0 AS pago_parcial_count,\r\n    CASE WHEN EXISTS (\r\n        SELECT 1 FROM pagamento_itens pi\r\n        WHERE pi.origem = 'funcao_imagem' AND pi.origem_id = fi.idfuncao_imagem\r\n          AND pi.observacao = 'Comissão Gestor'\r\n    ) THEN 1 ELSE 0 END AS pago_completa_count\r\nFROM \r\n    funcao_imagem fi\r\nJOIN \r\n    imagens_cliente_obra ico ON fi.imagem_id = ico.idimagens_cliente_obra\r\nJOIN \r\n    obra o ON ico.obra_id = o.idobra\r\nJOIN \r\n    funcao f ON fi.funcao_id = f.idfuncao\r\nJOIN \r\n    colaborador c ON c.idcolaborador = fi.colaborador_id\r\nLEFT JOIN (\r\n        SELECT h1.imagem_id, MAX(h1.status_id) AS status_id\r\n        FROM historico_imagens h1\r\n        INNER JOIN (\r\n            SELECT imagem_id, MAX(data_movimento) AS max_data\r\n            FROM historico_imagens\r\n            WHERE data_movimento <= ?\r\n            GROUP BY imagem_id\r\n        ) hm ON hm.imagem_id = h1.imagem_id AND hm.max_data = h1.data_movimento\r\n        GROUP BY h1.imagem_id\r\n    ) hi_snap ON hi_snap.imagem_id = ico.idimagens_cliente_obra\r\nWHERE \r\n    fi.colaborador_id IN (23, 40)\r\n    AND fi.funcao_id = 4\r\n    AND NOT (\r\n        EXISTS (\r\n            SELECT 1 FROM funcao_imagem fi_sub\r\n            JOIN funcao f_sub ON fi_sub.funcao_id = f_sub.idfuncao\r\n            WHERE fi_sub.imagem_id = fi.imagem_id\r\n              AND f_sub.nome_funcao = 'Pré-Finalização'\r\n        )\r\n        OR hi_snap.status_id = 1\r\n    ) AND (\r\n            (\r\n                (fi.status = 'Finalizado' OR fi.status = 'Em aprovação' OR fi.status = 'Ajuste' OR fi.status = 'Aprovado com ajustes' OR fi.status = 'Aprovado')\r\n                AND (YEAR(fi.prazo) = ? AND MONTH(fi.prazo) = ?)\r\n            )\r\n            OR EXISTS (\r\n                SELECT 1 FROM log_alteracoes la\r\n                WHERE la.funcao_imagem_id = fi.idfuncao_imagem\r\n                  AND MONTH(la.data) = ? AND YEAR(la.data) = ?\r\n                  AND LOWER(TRIM(la.status_novo)) IN ('finalizado', 'em aprovação', 'ajuste', 'aprovado com ajustes', 'aprovado')\r\n            )\r\n        )",
